import{_ as a,o as t,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"3.4.3 Create Agency","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-3-create-agency/spec.md","filePath":"feature/agency-workspace/3-4-3-create-agency/spec.md"}'),n={name:"feature/agency-workspace/3-4-3-create-agency/spec.md"};function r(s,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="_3-4-3-create-agency" tabindex="-1">3.4.3 Create Agency <a class="header-anchor" href="#_3-4-3-create-agency" aria-label="Permalink to &quot;3.4.3 Create Agency&quot;">​</a></h1><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>A signed-in user submits the Create Agency form — from the Agencies page (<code>/agencies/create</code>) or from a dialog opened on that page.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Signed-in user, who becomes the Owner of the Agency being created.</li><li><strong>Purpose:</strong> Let a user open a new Agency on BrandHub and start running their communications company from it.</li><li><strong>Interface:</strong> Create Agency page (<code>/agencies/create</code>) or a dialog on the Agencies page — a form with a required name field and a set of optional branding fields (logo, description, category, company size, website, phone, location, brand colour, logo icon, tagline, founded year, and the Facebook, LinkedIn and Instagram links).</li><li><strong>Data Processing:</strong> The system validates the submitted form, stores a new Agency with the current user as its Owner and the status ACTIVE, and records the same user as an Agency Member with the OWNER role in the same operation, so the Agency and its creator are permanently paired. The logo is uploaded afterwards through the Agency logo upload, once the Agency has an identifier.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Create Agency form:</p><ul><li>Name (required) and the optional branding fields listed above.</li><li>A logo picker: the file is uploaded after the Agency is created, not through the form itself.</li><li>A submit action; on success the user is taken into the newly created Agency.</li><li>The form is reachable from the Agencies page, where an empty state also offers the same call to action.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> Name of the Agency.</li><li><strong>Input optional:</strong> logoUrl, description, category (AgencyCategory: MARKETING, FNB, FASHION, BEAUTY, TECHNOLOGY, REAL_ESTATE, EDUCATION, HEALTHCARE, RETAIL, FINANCE, ENTERTAINMENT, OTHER), companySize (CompanySize: SIZE_1_10, SIZE_11_50, SIZE_51_200, SIZE_201_500, SIZE_500_PLUS), website, phone, location, brandColor (hex, at most 9 characters), logoIcon, tagline (at most 140 characters), foundedYear, facebookUrl, linkedinUrl, instagramUrl.</li><li><strong>System data:</strong> The Agency record — id, name, ownerId, logoUrl, description, category, companySize, website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, status (EntityStatus: ACTIVE / SOFT_DELETED), createdAt, updatedAt — and the Agency Member record that pairs the Agency with its Owner at the OWNER role.</li><li><strong>Output:</strong> The profile of the newly created Agency, including its identifier, its Owner and the status ACTIVE. The Agency is created as a new resource; the logo upload returns the same profile with the logo filled in.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-24 (analogous):</strong> Creating an Agency inserts the creator as an Agency Member with <code>role = OWNER</code>, mirroring the workspace-creation rule (BR-24) that auto-inserts the creator as <code>workspace_members</code> with <code>role = OWNER</code>. Name is mandatory; an empty name is refused with <code>400 VALIDATION_ERROR</code>.</li><li>Brand colour is limited to 9 characters and the tagline to 140 characters; a longer value is refused with <code>400 VALIDATION_ERROR</code>.</li><li>The creator becomes the Owner of the Agency, and an Agency Member record with the OWNER role is created for the same user. The pairing is fixed and cannot be reassigned by any other feature in the current scope.</li><li>The logo is not part of the main form. It is uploaded as a file through the Agency logo upload once the Agency identifier exists. A logo URL may still be passed as text, but the standard journey uploads the file separately.</li><li>On success the user is taken into the newly created Agency.</li><li>A user may own any number of Agencies; no creation limit is applied in the current scope. A limit may later come from the subscription plan.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Name empty → Display: MSG02</li><li>Brand colour longer than 9 characters, or tagline longer than 140 characters → Display: MSG03</li><li>No signed-in session → <code>401 UNAUTHORIZED</code> before any Agency logic runs.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The user opens the Create Agency form and fills in the name and, optionally, the branding fields.</li><li>The client submits the form.</li><li>The system validates the values against the rules above.</li><li>The system stores a new Agency with the current user as its Owner and the status ACTIVE.</li><li>The system stores an Agency Member record with the OWNER role for that same user.</li><li>The system returns the profile of the new Agency and the client moves the user into it; toast MSG31.</li><li>The user optionally uploads a logo file for the Agency; the system stores the file, fills in the logo of the Agency, and returns the updated profile; toast MSG94.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: Name left empty → <code>400 VALIDATION_ERROR</code>, Display: MSG02; nothing is created. 3.a2: The user fills in the name and resubmits.</li><li>3.b1: Brand colour or tagline over its limit → <code>400 VALIDATION_ERROR</code>, Display: MSG03; nothing is created. 3.b2: The user shortens the field and resubmits.</li><li>1.a1: No signed-in session → <code>401 UNAUTHORIZED</code>, toast MSG22. 1.a2: The user signs in again and retries.</li><li>7.a1: The logo file fails to be read during the logo upload → <code>400 FILE_READ_ERROR</code>, toast MSG29; the Agency itself remains created. 7.a2: The user selects a valid file and retries the upload.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>A new Agency exists with the current user as its Owner and the status ACTIVE.</li><li>An Agency Member record with the OWNER role exists for that user, pairing the Agency with its creator.</li><li>If a logo was uploaded, the Agency profile carries the logo URL and a refreshed update timestamp.</li></ul>',22)])])}const m=a(n,[["render",r]]);export{g as __pageData,m as default};
